using System.Net;
using System.Net.Http.Json;
using BuildingFlow.Application;
using BuildingFlow.Domain;
using Xunit;
namespace BuildingFlow.IntegrationTests;
public sealed class MobileTenantTests(SiteApiTests.SiteApiFactory factory):IClassFixture<SiteApiTests.SiteApiFactory>{
 private async Task<(HttpClient Client,Guid Property,Guid Unit,Guid Other,string User,Guid Membership,Guid Occupancy)> Setup(){
  var user=Guid.NewGuid().ToString();var property=new Property("Tenant fixture","City","District","Address");var b=property.AddBuilding("A");var unit=b.AddUnit("1",1,90m);var other=b.AddUnit("2",2,80m);
  Person Person(string name,string linked){var p=new Person(property.Id,name,"Fixture","5550000000",name+"@example.test");p.SetProfile("NATURAL","FOREIGN","US","PASSPORT123",null,null,null,linked);return p;}
  var tenant=Person("OwnTenant",user);var coTenant=Person("HiddenTenant",Guid.NewGuid().ToString());var owner=Person("HiddenOwner",Guid.NewGuid().ToString());
  var today=DateOnly.FromDateTime(TimeZoneInfo.ConvertTime(DateTimeOffset.UtcNow,TimeZoneInfo.FindSystemTimeZoneById("Europe/Istanbul")).DateTime);var period=new DateOnly(today.Year,today.Month,1);
  var occupancy=new UnitOccupancy(property.Id,unit.Id,tenant.Id,OccupancyType.TENANT,today.AddYears(-2));var coLink=new UnitOccupancy(property.Id,unit.Id,coTenant.Id,OccupancyType.TENANT,today.AddYears(-2));var ownerLink=new UnitOccupancy(property.Id,unit.Id,owner.Id,OccupancyType.OWNER,today.AddYears(-2));var membership=new PropertyMembership(property.Id,user);
  DuesAssessment Assessment(int month,decimal amount,string role){var a=new DuesAssessment(property.Id,Guid.NewGuid(),new string('a',64),period.AddMonths(month),amount,"TRY",today.AddDays(7),"Fixture charge",role);return a;}
  var unitAssessment=Assessment(0,100m,"UNIT");var unitCharge=unitAssessment.AddCharge(unit.Id);unitAssessment.AddCharge(other.Id);
  var tenantAssessment=Assessment(-1,80m,"TENANT");var ownCharge=tenantAssessment.AddCharge(unit.Id);ownCharge.RecordParties([new DuesChargeParty(ownCharge,occupancy,tenant,true)]);
  var coAssessment=Assessment(-2,400m,"TENANT");var coCharge=coAssessment.AddCharge(unit.Id);coCharge.RecordParties([new DuesChargeParty(coCharge,coLink,coTenant,true)]);
  var ownerAssessment=Assessment(-3,300m,"OWNER");var ownerCharge=ownerAssessment.AddCharge(unit.Id);ownerCharge.RecordParties([new DuesChargeParty(ownerCharge,ownerLink,owner,true)]);
  Payment Pay(DuesCharge charge,decimal amount){var p=new Payment(property.Id,unit.Id,Guid.NewGuid(),new string('b',64),amount,"TRY",today,PaymentMethod.BANK_TRANSFER,"private-"+Guid.NewGuid(),"Private bank description");p.Allocate(charge,amount);p.ValidateComplete();return p;}
  var unitPayment=Pay(unitCharge,30m);var tenantPayment=Pay(ownCharge,20m);var hiddenPayment=Pay(ownerCharge,40m);var cancelledPayment=Pay(unitCharge,10m);cancelledPayment.Cancel("Fixture reversal",DateTimeOffset.UtcNow);unitCharge.ReversePayment(10m);
  var note=new Announcement(property.Id,"Public note","Visible content",ContentAudience.ALL_MEMBERS);note.Publish(DateTimeOffset.UtcNow);var privateNote=new Announcement(property.Id,"Hidden management","Private content",ContentAudience.MANAGEMENT);privateNote.Publish(DateTimeOffset.UtcNow);
  await factory.WithDb(async db=>{db.AddRange(property,tenant,coTenant,owner,occupancy,coLink,ownerLink,membership,unitAssessment,tenantAssessment,coAssessment,ownerAssessment,unitPayment,tenantPayment,hiddenPayment,cancelledPayment,note,privateNote);db.Add(new MobileRequest(Guid.NewGuid(),property.Id,unit.Id,"TENANT",user,"Own tenant request"));db.Add(new MobileRequest(Guid.NewGuid(),property.Id,unit.Id,"OWNER",user,"Hidden role request"));db.Add(new MobileRequest(Guid.NewGuid(),property.Id,unit.Id,"TENANT","other","Hidden other request"));await db.SaveChangesAsync();});
  return(TestToken.Client(factory,user,"RESIDENT"),property.Id,unit.Id,other.Id,user,membership.Id,occupancy.Id);
 }
 private static string Path(Guid p,Guid u)=>$"/api/v1/mobile/tenant?propertyId={p}&unitId={u}";
 [PostgresFact] public async Task TenantSeesOnlyOwnDebtRelationshipAndAuthorizedAllocationHistory(){var s=await Setup();using var c=s.Client;var response=await c.GetAsync(Path(s.Property,s.Unit));Assert.Equal(HttpStatusCode.OK,response.StatusCode);var snapshot=(await response.Content.ReadFromJsonAsync<OwnerSnapshot>())!;Assert.EndsWith(":TENANT",snapshot.ContextKey);Assert.Equal("130.00",snapshot.Balance);Assert.Equal("0.00",snapshot.Overdue);Assert.Equal(2,snapshot.Charges.Length);Assert.Equal("OwnTenant Fixture",Assert.Single(snapshot.Tenants).Name);Assert.Equal(3,snapshot.Payments!.Length);Assert.Contains(snapshot.Payments,x=>x.Cancelled&&x.Amount=="10.00");Assert.DoesNotContain(snapshot.Payments,x=>x.Amount=="40.00");Assert.Single(snapshot.Announcements);Assert.Equal("Own tenant request",Assert.Single(snapshot.Requests).Description);var json=await response.Content.ReadAsStringAsync();foreach(var secret in new[]{"HiddenTenant","HiddenOwner","Hidden role","Hidden other","private-","Private bank","PASSPORT123","@example.test","5550000000"})Assert.DoesNotContain(secret,json,StringComparison.OrdinalIgnoreCase);}
 [PostgresFact] public async Task ForeignUnitPropertyRoleAndAnonymousCannotRead(){var s=await Setup();using var c=s.Client;Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,s.Other))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(Guid.NewGuid(),s.Unit))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync($"/api/v1/mobile/owner?propertyId={s.Property}&unitId={s.Unit}")).StatusCode);using var fake=TestToken.Client(factory,Guid.NewGuid().ToString(),"SUPER_ADMIN");Assert.Equal(HttpStatusCode.Forbidden,(await fake.GetAsync(Path(s.Property,s.Unit))).StatusCode);using var anon=TestToken.Client(factory,null,"");Assert.Equal(HttpStatusCode.Unauthorized,(await anon.GetAsync(Path(s.Property,s.Unit))).StatusCode);}
 [PostgresFact] public async Task MembershipRevocationBlocksSnapshotAndQueuedRequest(){var s=await Setup();using var c=s.Client;var command=new MobileSyncCommand(Guid.NewGuid(),Guid.NewGuid(),s.Property,s.Unit,"TENANT","CREATE",0,"Fixture request");Assert.Equal(HttpStatusCode.OK,(await c.PostAsJsonAsync("/api/v1/mobile/sync/commands",command)).StatusCode);await factory.WithDb(async db=>{var m=await db.PropertyMemberships.FindAsync(s.Membership);m!.SetEnabled(false);await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,s.Unit))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/v1/mobile/sync/commands",command)).StatusCode);}
 [PostgresFact] public async Task TenantRequestReplayAndExpiredRelationshipRemainScoped(){var s=await Setup();using var c=s.Client;var command=new MobileSyncCommand(Guid.NewGuid(),Guid.NewGuid(),s.Property,s.Unit,"TENANT","CREATE",0,"Fixture request");var first=(await (await c.PostAsJsonAsync("/api/v1/mobile/sync/commands",command)).Content.ReadFromJsonAsync<MobileSyncResult>())!;var again=(await (await c.PostAsJsonAsync("/api/v1/mobile/sync/commands",command)).Content.ReadFromJsonAsync<MobileSyncResult>())!;Assert.True(again.Replayed);Assert.Equal(first.Record.Id,again.Record.Id);Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/v1/mobile/sync/commands",command with{OperationId=Guid.NewGuid(),RecordId=Guid.NewGuid(),UnitId=s.Other})).StatusCode);await factory.WithDb(async db=>{var o=await db.UnitOccupancies.FindAsync(s.Occupancy);o!.End(DateOnly.FromDateTime(DateTime.UtcNow).AddDays(-2));await db.SaveChangesAsync();});Assert.Equal(HttpStatusCode.Forbidden,(await c.GetAsync(Path(s.Property,s.Unit))).StatusCode);Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/v1/mobile/sync/commands",command)).StatusCode);}
}
